    aboutHi: "\u0915\u0930\u094d\u0928\u093e\u091f\u0915 \u092d\u093e\u0930\u0924 \u0915\u0947 \u0926\u0915\u094d\u0937\u093f\u0923-\u092a\u0936\u094d\u091a\u093f\u092e \u092e\u0947\u0902 \u0938\u094d\u0925\u093f\u0924 \u0939\u0948\u0964 \u0907\u0938\u092e\u0947\u0902 \u0915\u0930\u093e\u0935\u0932\u0940 \u0924\u091f\u0940\u092f \u092e\u0948\u0926\u093e\u0928, \u092a\u0936\u094d\u091a\u093f\u092e\u0940 \u0918\u093e\u091f \u0915\u0947 \u0918\u0928\u0947 \u0935\u0930\u094d\u0937\u093e\u0935\u0928 (\u092e\u0932\u0947\u0928\u093e\u0921\u0941) \u0914\u0930 \u0926\u0915\u094d\u0915\u0928 \u0915\u093e \u092a\u0920\u093e\u0930\u0940 \u0915\u094d\u0937\u0947\u0924\u094d\u0930 (\u092c\u093e\u092f\u0932\u0942\u0938\u0940\u092e\u0947) \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902\u0964",
    aboutOr: "\u0b15\u0b30\u0b4d\u0b23\u0b4d\u0b23\u0b3e\u0b1f\u0b15 \u0b26\u0b15\u0b4d\u0b37\u0b3f\u0b23-\u0b2a\u0b36\u0b4d\u0b1a\u0b3f\u0b2e \u0b2d\u0b3e\u0b30\u0b24\u0b30\u0b47 \u0b05\u0b2c\u0b38\u0b4d\u0b25\u0b3f\u0b24\u0964 \u0b0f\u0b25\u0b3f\u0b30\u0b47 \u0b15\u0b3e\u0b30\u0b3e\u0b2d\u0b3e\u0b32\u0b3f \u0b24\u0b1f\u0b2c\u0b30\u0b4d\u0b24\u0b4d\u0b24\u0b40 \u0b05\u0b1e\u0b4d\u0b1a\u0b33, \u0b2a\u0b36\u0b4d\u0b1a\u0b3f\u0b2e\u0b18\u0b3e\u0b1f\u0b30 \u0b18\u0b1e\u0b4d\u0b1a \u0b2c\u0b30\u0b4d\u0b37\u0b3e\u0b2c\u0b23 (\u0b2e\u0b3e\u0b32\u0b28\u0b3e\u0b21) \u0b0f\u0b2c\u0b02 \u0b26\u0b3e\u0b15\u0b4d\u0b37\u0b3f\u0b23\u0b3e\u0b24\u0b4d\u0b5f \u0b2e\u0b3e\u0b33\u0b2d\u0b42\u0b2e\u0b3f \u0b05\u0b28\u0b4d\u0b24\u0b30\u0b4d\u0b2d\u0b41\u0b15\u0b4d\u0b24\u0964",
